// Normalize incoming Telegram message and match against curated Q&A pairs.
const item = $input.first().json;
const msg = item.message || {};
const chatId = msg.chat?.id;
const rawText = (msg.text || '').trim();

if (!chatId || !rawText) {
  return [{ json: { skip: true, reason: 'No text message or chatId' } }];
}

// Curated Q&A knowledge base (can also be loaded from Google Sheets / Notion / HTTP)
const qaPairs = [
  {
    id: 'hours',
    keywords: ['hours', 'open', 'working hours', 'schedule', 'time'],
    question: 'What are your support hours?',
    answer: 'Our support team is available Monday to Friday, 09:00–18:00 UTC.'
  },
  {
    id: 'pricing',
    keywords: ['price', 'pricing', 'cost', 'plan', 'fee'],
    question: 'How does your pricing work?',
    answer: 'We offer Starter ($29/mo), Pro ($79/mo), and Custom Enterprise plans. All plans include API access.'
  },
  {
    id: 'refund',
    keywords: ['refund', 'cancel', 'money back', 'return'],
    question: 'What is your refund policy?',
    answer: 'You can request a full refund within 14 days of purchase by replying with your order ID.'
  },
  {
    id: 'api',
    keywords: ['api', 'webhook', 'integration', 'token', 'docs'],
    question: 'Do you support REST API and webhooks?',
    answer: 'Yes! REST API keys and webhook endpoints can be generated directly in Settings > Developers.'
  }
];

const normalized = rawText.toLowerCase().replace(/[^a-z0-9\s]/g, ' ');
const tokens = new Set(normalized.split(/\s+/).filter(Boolean));

let bestMatch = null;
let bestScore = 0;

for (const entry of qaPairs) {
  let hits = 0;
  for (const kw of entry.keywords) {
    if (normalized.includes(kw)) {
      hits += 1;
    }
  }
  const score = hits / entry.keywords.length;
  if (score > bestScore) {
    bestScore = score;
    bestMatch = entry;
  }
}

const matched = bestScore >= 0.25 && bestMatch !== null;

return [{
  json: {
    skip: false,
    chatId,
    userQuery: rawText,
    matched,
    matchScore: Number(bestScore.toFixed(2)),
    matchedAnswer: matched ? bestMatch.answer : null,
    matchedQuestion: matched ? bestMatch.question : null,
    qaContext: qaPairs.map(q => `Q: ${q.question}\nA: ${q.answer}`).join('\n\n')
  }
}];

