const raw = $input.first().json;
const prev = $('Match Curated Q&A').first().json;
let parsed = { found: false, reply: '' };

try {
  const content = raw.choices?.[0]?.message?.content || '{}';
  parsed = JSON.parse(content);
} catch (e) {
  parsed = { found: false, reply: '' };
}

return [{
  json: {
    chatId: prev.chatId,
    found: Boolean(parsed.found && parsed.reply),
    replyText: parsed.found && parsed.reply
      ? parsed.reply
      : "Thanks for reaching out! I don't have an exact answer for that in our FAQ yet. Please contact support@example.com or share more details and a team member will help."
  }
}];
